package com.hrms.office.service;

import com.hrms.audit.service.AuditService;import com.hrms.auth.security.AuthPrincipal;import com.hrms.common.exceptions.*;import com.hrms.config.ApplicationProperties;import com.hrms.office.dto.*;import com.hrms.office.model.*;import com.hrms.office.repository.*;import com.hrms.assignment.model.AssignmentStatus;import com.hrms.assignment.repository.AssignmentRepository;import org.bson.types.ObjectId;import org.springframework.data.domain.Page;import org.springframework.data.mongodb.core.geo.GeoJsonPoint;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.Map;

@Service public class OfficeLocationService {
 private final OfficeLocationRepository offices;private final AssignmentRepository assignments;private final ApplicationProperties properties;private final AuditService audit;
 public OfficeLocationService(OfficeLocationRepository o,AssignmentRepository a,ApplicationProperties p,AuditService audit){offices=o;assignments=a;properties=p;this.audit=audit;}
 @Transactional public OfficeLocationResponse create(CreateOfficeLocationRequest r,AuthPrincipal actor){String code=r.locationCode().strip().toUpperCase();if(offices.existsByLocationCode(code))throw new ConflictException("Location code already exists");OfficeLocation o=map(r);o.setId(new ObjectId().toHexString());o.setLocationCode(code);o.setStatus(OfficeStatus.ACTIVE);o.setCreatedBy(actor.userId());o.setUpdatedBy(actor.userId());offices.save(o);audit.record(actor,"OFFICE_LOCATION_CREATED","OFFICE_LOCATION",o.getId(),Map.of(),Map.of("locationCode",code),null);return OfficeLocationResponse.from(o);}
 public OfficeLocationPageResponse list(OfficeSearch s){page(s.page(),s.limit());return OfficeLocationPageResponse.from(offices.search(s),s.limit());}public OfficeLocationResponse get(String id){return OfficeLocationResponse.from(find(id));}
 @Transactional public OfficeLocationResponse update(String id,UpdateOfficeLocationRequest r,AuthPrincipal actor){OfficeLocation o=find(id);if(r.locationCode()!=null&&!r.locationCode().strip().equalsIgnoreCase(o.getLocationCode())&&offices.existsByLocationCode(r.locationCode().strip().toUpperCase()))throw new ConflictException("Location code already exists");if(r.locationCode()!=null)o.setLocationCode(r.locationCode().strip().toUpperCase());if(r.name()!=null)o.setName(r.name().strip());if(r.description()!=null)o.setDescription(r.description().strip());if(r.addressLine1()!=null)o.setAddressLine1(r.addressLine1().strip());if(r.addressLine2()!=null)o.setAddressLine2(r.addressLine2().strip());if(r.city()!=null)o.setCity(r.city().strip());if(r.state()!=null)o.setState(r.state().strip());if(r.postalCode()!=null)o.setPostalCode(r.postalCode().strip());if(r.country()!=null)o.setCountry(r.country().strip());if(r.coordinates()!=null)o.setCoordinates(point(r.coordinates()));if(r.geofenceRadiusMeters()!=null)o.setGeofenceRadiusMeters(r.geofenceRadiusMeters());if(r.maximumGpsAccuracyMeters()!=null)o.setMaximumGpsAccuracyMeters(r.maximumGpsAccuracyMeters());o.setUpdatedBy(actor.userId());offices.save(o);audit.record(actor,"OFFICE_LOCATION_UPDATED","OFFICE_LOCATION",id,Map.of(),Map.of("locationCode",o.getLocationCode()),null);return OfficeLocationResponse.from(o);}
 @Transactional public OfficeLocationResponse deactivate(String id,AuthPrincipal actor){OfficeLocation o=find(id);if(o.getStatus()==OfficeStatus.INACTIVE)return OfficeLocationResponse.from(o);if(assignments.existsByOfficeLocationIdAndStatus(id,AssignmentStatus.ACTIVE))throw new ConflictException("End active employee assignments before deactivating this location");o.setStatus(OfficeStatus.INACTIVE);o.setUpdatedBy(actor.userId());offices.save(o);audit.record(actor,"OFFICE_LOCATION_DEACTIVATED","OFFICE_LOCATION",id,Map.of("status","ACTIVE"),Map.of("status","INACTIVE"),null);return OfficeLocationResponse.from(o);}
 @Transactional public OfficeLocationResponse reactivate(String id,AuthPrincipal actor){OfficeLocation o=find(id);if(o.getStatus()==OfficeStatus.ACTIVE)return OfficeLocationResponse.from(o);o.setStatus(OfficeStatus.ACTIVE);o.setUpdatedBy(actor.userId());offices.save(o);audit.record(actor,"OFFICE_LOCATION_REACTIVATED","OFFICE_LOCATION",id,Map.of("status","INACTIVE"),Map.of("status","ACTIVE"),null);return OfficeLocationResponse.from(o);}
 public void validateActive(String id){OfficeLocation o=find(id);if(o.getStatus()!=OfficeStatus.ACTIVE)throw new ConflictException("Office location is inactive");}
 private OfficeLocation map(CreateOfficeLocationRequest r){OfficeLocation o=new OfficeLocation();o.setName(r.name().strip());o.setDescription(trim(r.description()));o.setAddressLine1(r.addressLine1().strip());o.setAddressLine2(trim(r.addressLine2()));o.setCity(r.city().strip());o.setState(r.state().strip());o.setPostalCode(r.postalCode().strip());o.setCountry(r.country().strip());o.setCoordinates(point(r.coordinates()));o.setGeofenceRadiusMeters(r.geofenceRadiusMeters()==null?properties.geofence().defaultRadiusMeters():r.geofenceRadiusMeters());o.setMaximumGpsAccuracyMeters(r.maximumGpsAccuracyMeters()==null?properties.geofence().maxGpsAccuracyMeters():r.maximumGpsAccuracyMeters());return o;}
 private OfficeLocation findObj(String id){return offices.findById(id).orElseThrow(()->new ResourceNotFoundException("Office location was not found"));}private OfficeLocation find(String id){if(!ObjectId.isValid(id))throw new ApiException(ErrorCode.VALIDATION_ERROR,org.springframework.http.HttpStatus.BAD_REQUEST,"Office location id is invalid");return findObj(id);}private static GeoJsonPoint point(CoordinatesRequest c){return new GeoJsonPoint(c.longitude().doubleValue(),c.latitude().doubleValue());}private static String trim(String s){return s==null?null:s.strip();}private static void page(int p,int l){if(p<0||l<1||l>100)throw new ApiException(ErrorCode.VALIDATION_ERROR,org.springframework.http.HttpStatus.BAD_REQUEST,"Page must be non-negative and limit must be between 1 and 100");}
}
